// Guía de JouveERP — search box over window.GUIDE_INDEX (search-index.js,
// generated by `pnpm manual:build`). Same crude Spanish matching as the
// assistant's searchGuide (features/guide/manual/search.ts).

(function () {
  const input = document.getElementById("guide-search");
  const box = document.getElementById("guide-results");
  const index = window.GUIDE_INDEX || [];
  if (!input || !box) return;

  const STOP = new Set(
    "a al como con de del donde el en es hace hacer hago la las lo los me mi para por que se si su sus un una uno y o puedo quiero".split(
      " ",
    ),
  );

  function tokens(text) {
    return text
      .toLowerCase()
      .normalize("NFD")
      .replace(/[̀-ͯ]/g, "")
      .split(/[^a-z0-9]+/)
      .filter((t) => t.length > 1 && !STOP.has(t));
  }

  function stem(t) {
    return t.length <= 4 ? t : t.slice(0, Math.max(4, t.length - 3));
  }

  const docs = index.map((entry) => ({
    entry,
    title: new Set(tokens(entry.title).map(stem)),
    body: new Set(tokens(entry.path + " " + entry.text).map(stem)),
  }));

  function has(set, term) {
    for (const s of set) {
      if (s.startsWith(term) || term.startsWith(s)) return true;
    }
    return false;
  }

  function search(query) {
    const q = [...new Set(tokens(query).map(stem))];
    if (q.length === 0) return [];
    return docs
      .map((d) => {
        let score = 0;
        let hits = 0;
        for (const term of q) {
          const w = has(d.title, term) ? 3 : has(d.body, term) ? 1 : 0;
          score += w;
          if (w) hits += 1;
        }
        return { d, score: score * (hits / q.length) };
      })
      .filter((x) => x.score > 0)
      .sort((a, b) => b.score - a.score)
      .slice(0, 12)
      .map((x) => x.d.entry);
  }

  let active = 0;

  function render() {
    const hits = search(input.value);
    box.replaceChildren();
    if (!input.value.trim()) {
      box.hidden = true;
      return;
    }
    if (hits.length === 0) {
      const p = document.createElement("p");
      p.textContent = "Sin resultados. Probá con otras palabras.";
      box.append(p);
    }
    hits.forEach((hit, i) => {
      const a = document.createElement("a");
      a.href = hit.href;
      if (i === active) a.className = "active";
      const strong = document.createElement("strong");
      strong.textContent = hit.title;
      const small = document.createElement("small");
      small.textContent = hit.path;
      a.append(strong, small);
      box.append(a);
    });
    box.hidden = false;
  }

  input.addEventListener("input", () => {
    active = 0;
    render();
  });

  input.addEventListener("keydown", (event) => {
    const links = box.querySelectorAll("a");
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      const step = event.key === "ArrowDown" ? 1 : -1;
      active = Math.max(0, Math.min(links.length - 1, active + step));
      render();
    } else if (event.key === "Enter" && links[active]) {
      window.location.href = links[active].href;
    } else if (event.key === "Escape") {
      input.value = "";
      render();
    }
  });

  document.addEventListener("click", (event) => {
    if (!box.contains(event.target) && event.target !== input)
      box.hidden = true;
  });

  // "/" focuses the search, like many docs sites.
  document.addEventListener("keydown", (event) => {
    if (event.key === "/" && document.activeElement !== input) {
      event.preventDefault();
      input.focus();
    }
  });
})();
